+            throw new UncheckedIOException(e);
+        }
+
+        if (classWriter != null) {
+            try (var out = Files.newOutputStream(file)) {
+                out.write(classWriter.toByteArray());
+            } catch (IOException e) {
+                throw new org.gradle.api.UncheckedIOException(e);
+            }
+        }
+
+    }
