+            {
+                b.startObject("to");
+                {
+                    b.field("int_value", intValue);
+                    b.startObject("some");
+                    {
+                        b.startObject("deeply");
+                        {
+                            b.startObject("nested");
+                            b.field("string_value", stringValue);
+                            b.endObject();
+                        }
+                        b.endObject();
+                    }
+                    b.endObject();
+                }
+                b.endObject();
+            }
+            b.endObject();
