+            var groupDoc = new GroupDoc(id, Integer.toString(group), firstPassScore, secondPassScore, shouldFilter);
+            if (shouldFilter == false) {
+                if (firstPassScore == bestScore) {
+                    // avoid tiebreaker
+                    continue;
+                }
+
+                numHits++;
+                if (firstPassScore > bestScore) {
+                    groups[group] = groupDoc;
+                }
+            }
+            requests.add(
