+        String method = "(?<method>GET|PUT|POST|HEAD|OPTIONS|DELETE)";
+        String pathAndQuery = "(?<pathAndQuery>[^\\n]+)";
+
+        String badBody = "GET|PUT|POST|HEAD|OPTIONS|DELETE|startyaml|#";
+        String body = "(?<body>(?:\\n(?!" + badBody + ")[^\\n]+)+)";
