+        String rawRequest = "(?:" + method + "\\s+" + pathAndQuery + body + "?)";
+
+        String yamlRequest = "(?:startyaml(?s)(?<yaml>.+?)(?-s)endyaml)";
+        String nonComment = "(?:" + rawRequest + "|" + yamlRequest + ")";
+        String comment = "(?<comment>#.+)";
+
+        String SYNTAX = "(?:" + comment + "|" + nonComment + ")\\n+";
